  1	//! A faithful re-implementation of C++'s `std::stoi`.
  2	//!
  3	//! `std::stoi(str)` is specified as a `std::strtol` call with base 10 whose
  4	//! result is narrowed to `int`. That means it is *prefix* parsing, not
  5	//! whole-string parsing, and it reports failure by throwing:
  6	//!
  7	//! * leading whitespace (`" \t\n\v\f\r"`) is skipped;
  8	//! * an optional `+` or `-` sign may follow;
  9	//! * decimal digits are then consumed for as long as they appear, and the rest
 10	//!   of the string is ignored — `"3abc"` is `3`, `"12.9"` is `12`, `"1e3"` is
 11	//!   `1`, and `"0x10"` is `0` (base 10 gives `0x` no special meaning);
 12	//! * if no digit was consumed it throws `std::invalid_argument`;
 13	//! * if the value does not fit in `int` it throws `std::out_of_range`.
 14	//!
 15	//! Both exceptions carry `what() == "stoi"`.
 16	
 17	/// Why a [`stoi`] call failed, mirroring the exception C++ would throw.
 18	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
 19	pub enum StoiError {
 20	    /// No digits were found: C++ throws `std::invalid_argument`.
 21	    InvalidArgument,
 22	    /// Digits were found but the value does not fit in `int`: C++ throws
 23	    /// `std::out_of_range`.
 24	    OutOfRange,
 25	}
 26	
 27	impl StoiError {
 28	    /// The fully qualified C++ exception type this corresponds to.
 29	    pub fn exception_type(self) -> &'static str {
 30	        match self {
 31	            StoiError::InvalidArgument => "std::invalid_argument",
 32	            StoiError::OutOfRange => "std::out_of_range",
 33	        }
 34	    }
 35	
 36	    /// The exception's `what()` string, which for `std::stoi` is the function
 37	    /// name.
 38	    pub fn what(self) -> &'static str {
 39	        "stoi"
 40	    }
 41	}
 42	
 43	impl std::fmt::Display for StoiError {
 44	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
 45	        write!(f, "{}: {}", self.exception_type(), self.what())
 46	    }
 47	}
 48	
 49	impl std::error::Error for StoiError {}
 50	
 51	/// True for the characters C++'s `isspace` accepts in the default "C" locale.
 52	fn is_cxx_space(c: char) -> bool {
 53	    matches!(c, ' ' | '\t' | '\n' | '\u{b}' | '\u{c}' | '\r')
 54	}
 55	
 56	/// Parses a leading `int` out of `s` exactly as C++'s `std::stoi(s)` does.
 57	///
 58	/// # Examples
 59	///
 60	/// ```ignore
 61	/// assert_eq!(stoi("42"), Ok(42));
 62	/// assert_eq!(stoi("  -7xyz"), Ok(-7));
 63	/// assert_eq!(stoi("0x10"), Ok(0));
 64	/// assert_eq!(stoi("abc"), Err(StoiError::InvalidArgument));
 65	/// assert_eq!(stoi("2147483648"), Err(StoiError::OutOfRange));
 66	/// ```
 67	pub fn stoi(s: &str) -> Result<i32, StoiError> {
 68	    stoi_with_pos(s).map(|(value, _)| value)
 69	}
 70	
 71	/// Like [`stoi`], but also reports how many bytes were consumed — the value
 72	/// `std::stoi` writes through its optional `pos` out-parameter.
 73	pub fn stoi_with_pos(s: &str) -> Result<(i32, usize), StoiError> {
 74	    let bytes = s.as_bytes();
 75	    let mut i = 0;
 76	
 77	    while i < bytes.len() && is_cxx_space(bytes[i] as char) {
 78	        i += 1;
 79	    }
 80	
 81	    let negative = match bytes.get(i) {
 82	        Some(b'-') => {
 83	            i += 1;
 84	            true
 85	        }
 86	        Some(b'+') => {
 87	            i += 1;
 88	            false
 89	        }
 90	        _ => false,
 91	    };
 92	
 93	    let digits_start = i;
 94	    // Accumulate the magnitude. `strtol` keeps scanning digits after it has
 95	    // overflowed (so the reported end position still covers them all) and then
 96	    // reports a range error, so overflow is latched rather than returned early.
 97	    let mut magnitude: u64 = 0;
 98	    let mut overflowed = false;
 99	    while i < bytes.len() && bytes[i].is_ascii_digit() {
100	        let digit = u64::from(bytes[i] - b'0');
101	        if !overflowed {
102	            match magnitude.checked_mul(10).and_then(|m| m.checked_add(digit)) {
103	                Some(next) => magnitude = next,
104	                None => overflowed = true,
105	            }
106	        }
107	        i += 1;
108	    }
109	
110	    if i == digits_start {
111	        // Not a single digit: `strtol` consumed nothing, so `stoi` throws.
112	        return Err(StoiError::InvalidArgument);
113	    }
114	
115	    // `int` is two's-complement 32-bit, so the negative range extends one
116	    // further than the positive one.
117	    let limit: u64 = if negative {
118	        i32::MAX as u64 + 1
119	    } else {
120	        i32::MAX as u64
121	    };
122	    if overflowed || magnitude > limit {
123	        return Err(StoiError::OutOfRange);
124	    }
125	
126	    let value = if negative {
127	        (magnitude as i64).wrapping_neg() as i32
128	    } else {
129	        magnitude as i32
130	    };
131	    Ok((value, i))
132	}
