134	/// Reproduces what a C++ program does when an exception escapes `main`.
135	///
136	/// The runtime prints the `terminate called after throwing …` banner on stderr
137	/// and calls `std::abort`, which leaves the process killed by `SIGABRT` (shell
138	/// exit status 134). [`std::process::abort`] raises the same signal, so the port
139	/// is observably identical down to the exit status.
140	pub fn terminate_with_uncaught_exception(error: StoiError) -> ! {
141	    eprint!(
142	        "terminate called after throwing an instance of '{}'\n  what():  {}\n",
143	        error.exception_type(),
144	        error.what()
145	    );
146	    std::process::abort()
147	}
