253	/// Grafts a full `leaf` into the trie rooted at `parent`.
254	///
255	/// `size` is the element count *before* the push, so `size - 1` is the index of
256	/// the last element of the leaf being inserted, and its radix digits spell out
257	/// where the leaf belongs. At each level the digit either selects an existing
258	/// child to recurse into or points one past the last child, meaning a fresh
259	/// spine has to be created there.
260	fn push_leaf<T>(
261	    size: usize,
262	    level: u32,
263	    parent: &Rc<Node<T>>,
264	    leaf: Rc<Node<T>>,
265	) -> Rc<Node<T>> {
266	    let subidx = ((size - 1) >> level) & MASK;
267	    let children = parent.children();
268	    // The trie fills left-to-right, so the digit either selects a child that
269	    // already exists or points at the very next slot. Note that a node may well
270	    // be at full width (32 children) and still be the right place to recurse
271	    // into: its last child can have room inside it.
272	    debug_assert!(subidx <= children.len(), "the trie fills left-to-right with no gaps");
273	    debug_assert!(
274	        subidx < BRANCHING && children.len() <= BRANCHING,
275	        "a node never exceeds its branching factor"
276	    );
277	
278	    let insert = if level == BITS {
279	        // One level above the leaves: this is where the leaf lands.
280	        leaf
281	    } else if subidx < children.len() {
282	        push_leaf(size, level - BITS, &children[subidx], leaf)
283	    } else {
284	        new_path(level - BITS, leaf)
285	    };
286	
287	    // Copy this node (cheap: a vector of at most 32 reference-count bumps) and
288	    // splice in the rebuilt child. Every sibling subtree stays shared.
289	    let mut copy = children.clone();
290	    if subidx < copy.len() {
291	        copy[subidx] = insert;
292	    } else {
293	        copy.push(insert);
294	    }
295	    Rc::new(Node::Inner(copy))
296	}
297	
298	/// Rebuilds the path to index `i`, replacing that element with `value`.
299	fn update_path<T: Clone>(i: usize, level: u32, node: &Rc<Node<T>>, value: T) -> Rc<Node<T>> {
300	    if level == 0 {
301	        let mut elems = node.elems().to_vec();
302	        elems[i & MASK] = value;
303	        return Rc::new(Node::Leaf(elems));
304	    }
305	    let children = node.children();
306	    let subidx = (i >> level) & MASK;
307	    let mut copy = children.clone();
308	    copy[subidx] = update_path(i, level - BITS, &children[subidx], value);
309	    Rc::new(Node::Inner(copy))
310	}
