  1	//! Trie node representation for the persistent vector.
  2	//!
  3	//! `immer::vector` (like Clojure's `PersistentVector` and the RRB-tree family it
  4	//! is derived from) stores its elements in a *bit-partitioned vector trie*: a
  5	//! tree of fixed-width nodes where the radix-`B` digits of an element's index
  6	//! spell out the path from the root down to the leaf holding it.
  7	//!
  8	//! With a branching factor of `B = 32` each level consumes `BITS = 5` bits of
  9	//! the index, so lookup is `O(log32 n)` — effectively constant for any vector
 10	//! that fits in memory — and `push_back` only has to copy the `O(log32 n)` nodes
 11	//! along one root-to-leaf path. Every untouched node is shared with the previous
 12	//! version through reference counting, which is what makes the structure
 13	//! *persistent*: the old vector stays alive, valid, and unchanged.
 14	
 15	use std::rc::Rc;
 16	
 17	/// Number of index bits consumed per trie level.
 18	pub const BITS: u32 = 5;
 19	
 20	/// Branching factor of the trie: `2^BITS` children per inner node.
 21	pub const BRANCHING: usize = 1 << BITS;
 22	
 23	/// Mask selecting the index bits belonging to a single level.
 24	pub const MASK: usize = BRANCHING - 1;
 25	
 26	/// A node of the vector trie.
 27	///
 28	/// Nodes are always reached through an [`Rc`], which is what implements the
 29	/// structural sharing between vector versions. A node is immutable once built;
 30	/// "modifying" a vector means building fresh nodes along one path and sharing
 31	/// every sibling subtree with the source vector.
 32	///
 33	/// Invariants (upheld by [`super::vector::Vector`]):
 34	///
 35	/// * A node at level `l > 0` is always [`Node::Inner`]; a node at level `0` is
 36	///   always [`Node::Leaf`].
 37	/// * Children are packed left-to-right with no gaps, so an inner node's
 38	///   `children.len()` is exactly its number of populated slots.
 39	/// * `children.len() <= BRANCHING` and `elems.len() <= BRANCHING`.
 40	/// * Every leaf that lives *inside the trie* is completely full
 41	///   (`elems.len() == BRANCHING`); a partially filled trailing leaf is held
 42	///   outside the trie, in the vector's tail.
 43	pub enum Node<T> {
 44	    /// Interior node: `BRANCHING`-way fan-out to child nodes one level down.
 45	    Inner(Vec<Rc<Node<T>>>),
 46	    /// Leaf node: a chunk of up to `BRANCHING` consecutive elements.
 47	    Leaf(Vec<T>),
 48	}
 49	
 50	impl<T> Node<T> {
 51	    /// A fresh inner node with no children.
 52	    pub fn empty_inner() -> Rc<Node<T>> {
 53	        Rc::new(Node::Inner(Vec::new()))
 54	    }
 55	
 56	    /// The children of an inner node.
 57	    ///
 58	    /// # Panics
 59	    ///
 60	    /// Panics if called on a leaf, which would mean the level bookkeeping in
 61	    /// [`super::vector::Vector`] had gone wrong.
 62	    pub fn children(&self) -> &Vec<Rc<Node<T>>> {
 63	        match self {
 64	            Node::Inner(children) => children,
 65	            Node::Leaf(_) => unreachable!("expected an inner node, found a leaf"),
 66	        }
 67	    }
 68	
 69	    /// The elements of a leaf node.
 70	    ///
 71	    /// # Panics
 72	    ///
 73	    /// Panics if called on an inner node.
 74	    pub fn elems(&self) -> &[T] {
 75	        match self {
 76	            Node::Leaf(elems) => elems,
 77	            Node::Inner(_) => unreachable!("expected a leaf, found an inner node"),
 78	        }
 79	    }
 80	
 81	    /// Whether this node is a leaf.
 82	    pub fn is_leaf(&self) -> bool {
 83	        matches!(self, Node::Leaf(_))
 84	    }
 85	}
 86	
 87	/// Builds the single-child chain that hangs a finished leaf at depth `level`.
 88	///
 89	/// When a new leaf has to be attached somewhere the trie has no branch yet, the
 90	/// intervening inner nodes must be created: `new_path` returns a spine of
 91	/// one-child nodes from `level` down to the leaf. `level == 0` means "the leaf
 92	/// belongs right here", so the node is returned as-is.
 93	pub fn new_path<T>(level: u32, node: Rc<Node<T>>) -> Rc<Node<T>> {
 94	    debug_assert!(node.is_leaf(), "new_path always terminates in a leaf");
 95	    if level == 0 {
 96	        node
 97	    } else {
 98	        Rc::new(Node::Inner(vec![new_path(level - BITS, node)]))
 99	    }
100	}
101	//! Forward iteration over a persistent vector.
102	//!
103	//! The naive way to iterate a vector trie is to call the indexing routine once
104	//! per element, which re-descends the trie every time: `O(n log n)` overall.
105	//! [`Iter`] instead keeps the current root-to-leaf path on an explicit stack and
106	//! walks it like an odometer, so each `next()` is amortised `O(1)` and a full
107	//! traversal is `O(n)` — the same shape as the chunked iterators the C++
108	//! original uses.
109	
110	use std::rc::Rc;
111	
112	use super::node::Node;
113	use super::vector::Vector;
114	
115	/// Borrowing forward iterator over the elements of a [`Vector`].
116	///
117	/// Created by [`Vector::iter`], or by `for x in &vector`.
118	pub struct Iter<'a, T> {
119	    /// The inner nodes on the path to `leaf`, each paired with the index of the
120	    /// child *after* the one we descended into.
121	    stack: Vec<(&'a [Rc<Node<T>>], usize)>,
122	    /// The chunk currently being handed out (a trie leaf, or the tail).
123	    leaf: &'a [T],
124	    /// How far into `leaf` we are.
125	    pos: usize,
126	    /// The vector's trailing chunk, visited once the trie is exhausted.
127	    tail: &'a [T],
128	    /// Whether `leaf` is already the tail.
129	    in_tail: bool,
130	    /// Total elements not yet yielded; drives `size_hint`.
131	    left: usize,
132	}
133	
134	impl<'a, T> Iter<'a, T> {
135	    pub(super) fn new(vector: &'a Vector<T>) -> Iter<'a, T> {
136	        let mut iter = Iter {
137	            stack: Vec::new(),
138	            leaf: &[],
139	            pos: 0,
140	            tail: vector.tail_slice(),
141	            in_tail: false,
142	            left: vector.size(),
143	        };
144	        if vector.tail_offset() > 0 {
145	            // The trie holds elements: prime `leaf` with its leftmost chunk.
146	            iter.descend(vector.root());
147	        } else {
148	            // Everything the vector has (if anything) lives in the tail.
149	            iter.enter_tail();
150	        }
151	        iter
152	    }
153	
154	    /// Descends from `node` to its leftmost leaf, recording the path so
155	    /// [`Iter::advance_chunk`] can resume from it.
156	    fn descend(&mut self, node: &'a Rc<Node<T>>) {
157	        let mut node: &'a Node<T> = node;
158	        while !node.is_leaf() {
159	            let children = node.children();
160	            debug_assert!(!children.is_empty(), "populated subtrees are never empty");
161	            self.stack.push((children, 1));
162	            node = &children[0];
163	        }
164	        self.leaf = node.elems();
165	        self.pos = 0;
166	    }
167	
168	    /// Switches the iterator over to the tail chunk.
169	    fn enter_tail(&mut self) {
170	        self.in_tail = true;
171	        self.leaf = self.tail;
172	        self.pos = 0;
173	    }
174	
175	    /// Moves to the next chunk once the current one is used up.
176	    fn advance_chunk(&mut self) {
177	        if self.in_tail {
178	            // Nothing follows the tail.
179	            self.leaf = &[];
180	            self.pos = 0;
181	            return;
182	        }
183	        // Odometer step: unwind to the deepest level that still has an
184	        // unvisited child, then take that subtree's leftmost leaf.
185	        while let Some((children, next)) = self.stack.pop() {
186	            if next < children.len() {
187	                self.stack.push((children, next + 1));
188	                let child = &children[next];
189	                self.descend(child);
190	                return;
191	            }
192	        }
193	        // The trie is exhausted; the tail is what remains.
194	        self.enter_tail();
195	    }
196	}
