198	impl<'a, T> Iterator for Iter<'a, T> {
199	    type Item = &'a T;
200	
201	    fn next(&mut self) -> Option<&'a T> {
202	        if self.left == 0 {
203	            return None;
204	        }
205	        while self.pos >= self.leaf.len() {
206	            self.advance_chunk();
207	            if self.leaf.is_empty() {
208	                // Unreachable while `left > 0`: the size and the structure agree.
209	                return None;
210	            }
211	        }
212	        let item = &self.leaf[self.pos];
213	        self.pos += 1;
214	        self.left -= 1;
215	        Some(item)
216	    }
217	
218	    fn size_hint(&self) -> (usize, Option<usize>) {
219	        (self.left, Some(self.left))
220	    }
221	}
222	
223	impl<'a, T> ExactSizeIterator for Iter<'a, T> {
224	    fn len(&self) -> usize {
225	        self.left
226	    }
227	}
228	
229	impl<'a, T> std::iter::FusedIterator for Iter<'a, T> {}
