231	/// Consuming iterator, yielding clones of the elements in order.
232	///
233	/// A persistent vector's storage may still be shared with other versions, so the
234	/// elements cannot be moved out; cloning is the faithful behaviour.
235	pub struct IntoIter<T> {
236	    vector: Vector<T>,
237	    index: usize,
238	}
239	
240	impl<T> IntoIter<T> {
241	    pub(super) fn new(vector: Vector<T>) -> IntoIter<T> {
242	        IntoIter { vector, index: 0 }
243	    }
244	}
245	
246	impl<T: Clone> Iterator for IntoIter<T> {
247	    type Item = T;
248	
249	    fn next(&mut self) -> Option<T> {
250	        let item = self.vector.get(self.index)?.clone();
251	        self.index += 1;
252	        Some(item)
253	    }
254	
255	    fn size_hint(&self) -> (usize, Option<usize>) {
256	        let left = self.vector.size() - self.index;
257	        (left, Some(left))
258	    }
259	}
