285	//! C++ `int` arithmetic.
286	//!
287	//! The C++ original accumulates into `int` variables (`auto sum = 0;` deduces
288	//! `int`, and the elements are `int`). Rust's `+`/`*` panic on overflow in debug
289	//! builds and wrap in release builds, so neither operator on its own reproduces
290	//! the reference binary: GCC/Clang on x86-64 compile signed overflow to
291	//! two's-complement wrap-around, which is what the reference output shows.
292	//!
293	//! For example `n = 46341` prints `1073767311` and then `-2147432674`: the
294	//! doubled sum is `2147534622`, which wraps to `2147534622 - 2^32`. Using these
295	//! helpers keeps that behaviour explicit — and identical in debug and release.
296	
297	/// Rust equivalent of C++'s `int` on every mainstream platform: 32-bit,
298	/// two's-complement.
299	pub type CInt = i32;
300	
301	/// `a + b` with the wrap-around a C++ compiler emits for `int` overflow.
302	#[inline]
303	pub fn add(a: CInt, b: CInt) -> CInt {
304	    a.wrapping_add(b)
305	}
306	
307	/// `a * b` with the wrap-around a C++ compiler emits for `int` overflow.
308	#[inline]
309	pub fn mul(a: CInt, b: CInt) -> CInt {
310	    a.wrapping_mul(b)
311	}
