348	//! Access to `argv`, matching the C++ program's view of it.
349	
350	/// The process arguments, including `argv[0]`, so that indices line up with the
351	/// C++ `argv` and `args().len()` equals `argc`.
352	///
353	/// This is [`std::env::args`] with one deliberate difference: `std::env::args`
354	/// panics if any argument is not valid UTF-8, whereas C++ hands `main` raw bytes
355	/// and never fails. Going through [`std::env::args_os`] and replacing invalid
356	/// bytes keeps the C++ behaviour — such bytes are not digits, so the parse
357	/// outcome is the same one `std::stoi` would reach.
358	pub fn args() -> Vec<String> {
359	    std::env::args_os()
360	        .map(|arg| arg.to_string_lossy().into_owned())
361	        .collect()
362	}
363	
364	/// The `index`-th argument (`argv[index]`), or `None` when `argc <= index`.
365	pub fn arg(index: usize) -> Option<String> {
366	    args().into_iter().nth(index)
367	}
